import paramiko
c = paramiko.SSHClient()
c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
c.connect('46.202.154.25', 22, 'root', '2N00py123+++')
# Use ALERT + visible log
fix = b'''<!doctype html>
<html>
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Arelorian</title>
<link rel="stylesheet" href="/assets/MMORPGClientCore-Bf6Bj3Nv.css">
<link rel="stylesheet" href="/assets/main-hKkHMhy1.css">
<script>
var logmsg='START';
function upd(t){
  logmsg=t;
  document.getElementById('log').innerText=t;
}
HTMLCanvasElement.prototype._gc=HTMLCanvasElement.prototype.getContext;
HTMLCanvasElement.prototype.getContext=function(type,opts){
  upd('getContext: '+type);
  if(type==='webgl2')type='webgl';
  var o=Object.assign({failIfMajorPerformanceCaveat:false},opts);
  var ctx=this._gc(type,o);
  upd('getContext: '+type+' = '+(ctx?'OK':'FAIL'));
  return ctx;
};
</script>
<script src="/assets/vendor-BVz5TCBb.js"></script>
<script src="/assets/MMORPGClientCore-DLUgQ5Dc.js"></script>
<script src="/assets/services-C3ENgesv.js"></script>
<script src="/assets/rolldown-runtime-DwmM5USC.js"></script>
<script src="/assets/main-CLZYnZ3S.js"></script>
<style>
html,body{margin:0;background:#000;height:100%}
#application-canvas{width:100%;height:100%}
#log{position:fixed;top:0;left:0;right:0;background:#222;color:#0f0;padding:10px;font-size:14px;z-index:9999}
</style>
</head>
<body>
<div id="log">INIT...</div>
<canvas id="application-canvas"></canvas>
</body>
</html>'''
sftp = c.open_sftp()
with sftp.file('/tmp/game.html', 'wb') as f:
    f.write(fix)
c.exec_command('cp /tmp/game.html /opt/areloria/client/dist/index.html')
print('Debug v2')
c.close()
EOF
